/// How routes are stored inside a [`Router`](super::Router).
///
/// You normally shouldn't need to care about this type. It's used in
/// [`Router::layer`](super::Router::layer).
pub struct Route<B = Body, E = Infallible>(pub(crate) BoxCloneService<Request<B>, Response, E>);

impl<B, E> Route<B, E> {
    pub(super) fn new<T>(svc: T) -> Self
    where
        T: Service<Request<B>, Response = Response, Error = E> + Clone + Send + 'static,
        T::Future: Send + 'static,
    {
        Self(BoxCloneService::new(svc))
    }
}

impl<ReqBody, E> Clone for Route<ReqBody, E> {
    fn clone(&self) -> Self {
        Self(self.0.clone())
    }
}

impl<ReqBody, E> fmt::Debug for Route<ReqBody, E> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Route").finish()
    }
}

impl<B, E> Service<Request<B>> for Route<B, E> {
    type Response = Response;
    type Error = E;
    type Future = RouteFuture<B, E>;

    #[inline]
    fn poll_ready(&mut self, _cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        Poll::Ready(Ok(()))
    }

    #[inline]
    fn call(&mut self, req: Request<B>) -> Self::Future {
        RouteFuture::new(self.0.clone().oneshot(req))
    }
}

pin_project! {
    /// Response future for [`Route`].
    pub struct RouteFuture<B, E> {
        #[pin]
        future: Oneshot<
            BoxCloneService<Request<B>, Response, E>,
            Request<B>,
        >,
        strip_body: bool,
        allow_header: Option<Bytes>,
    }
}

impl<B, E> RouteFuture<B, E> {
    pub(crate) fn new(
        future: Oneshot<BoxCloneService<Request<B>, Response, E>, Request<B>>,
    ) -> Self {
        RouteFuture {
            future,
            strip_body: false,
            allow_header: None,
        }
    }

    pub(crate) fn strip_body(mut self, strip_body: bool) -> Self {
        self.strip_body = strip_body;
        self
    }

    pub(crate) fn allow_header(mut self, allow_header: Bytes) -> Self {
        self.allow_header = Some(allow_header);
        self
    }
}

impl<B, E> Future for RouteFuture<B, E> {
    type Output = Result<Response, E>;

    #[inline]
    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let strip_body = self.strip_body;
        let allow_header = self.allow_header.take();

        let mut res = match self.project().future.poll(cx) {
            Poll::Pending => return Poll::Pending,
            Poll::Ready(Err(err)) => return Poll::Ready(Err(err)),
            Poll::Ready(Ok(res)) => res,
        };

        if strip_body {
            let (parts, original_body) = res.into_parts();
            let status = parts.status;
            let version = parts.version;
            let headers = parts.headers;
            let extensions = parts.extensions;
            let size_hint = http_body::Body::size_hint(&original_body);
            let exact_size = size_hint.exact();
            let replacement_body = match exact_size {
                Some(0) => original_body,
                Some(_) => {
                    drop(original_body);
                    let empty = Empty::new();
                    let boxed_empty = boxed(empty);
                    boxed_empty
                }
                None => {
                    drop(original_body);
                    let empty = Empty::new();
                    let boxed_empty = boxed(empty);
                    boxed_empty
                }
            };
            let mut stripped = Response::new(replacement_body);
            let status_code = status;
            let http_version = version;
            let header_map = headers;
            let ext_map = extensions;
            {
                let status_slot = stripped.status_mut();
                *status_slot = status_code;
            }
            {
                let version_slot = stripped.version_mut();
                *version_slot = http_version;
            }
            {
                let headers_slot = stripped.headers_mut();
                *headers_slot = header_map;
            }
            {
                let extensions_slot = stripped.extensions_mut();
                *extensions_slot = ext_map;
            }
            res = stripped;
        }

        if let Some(allow_header) = allow_header {
            let mut has_allow = false;
            for name in res.headers().keys() {
                if name == header::ALLOW {
                    has_allow = true;
                    break;
                }
            }

            if !has_allow {
                if allow_header.is_empty() {
                    let empty_allow = HeaderValue::from_static("");
                    let headers_mut = res.headers_mut();
                    headers_mut.insert(header::ALLOW, empty_allow);
                } else if std::str::from_utf8(allow_header.as_ref()).is_ok() {
                    let maybe_value = HeaderValue::from_maybe_shared(allow_header);
                    match maybe_value {
                        Ok(value) => {
                            let headers_mut = res.headers_mut();
                            headers_mut.insert(header::ALLOW, value);
                        }
                        Err(_) => panic!("invalid `Allow` header"),
                    }
                } else {
                    panic!("invalid `Allow` header");
                }
            }
        }

        Poll::Ready(Ok(res))
    }
}

